import{_ as o,C as t,o as s,c as i,E as a,a2 as c}from"./chunks/framework.BOeh4kYD.js";const h="/joinwell52/assets/current-context-20260916/failed-check-memory.figure.en.svg",f=JSON.parse('{"title":"The check failed. Why did the AI remember the answer?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The check failed. Why did the AI remember the answer?","date":"2026-09-16","published_date":"2026-09-16","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The check failed. Why did the AI remember the answer?","summary":"A failed run can still leave an unchecked answer in the next conversation. A controlled experiment separates the error shown now from the history replayed later.","cover":"/assets/current-context-20260916/failed-check-memory.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments on pinned source; scope in article","pageClass":"current-context-article"},"headers":[],"relativePath":"en/engineering/2026-09-16-failed-check-memory.md","filePath":"en/engineering/2026-09-16-failed-check-memory.md","lastUpdated":1789531953000}'),d={name:"en/engineering/2026-09-16-failed-check-memory.md"};function l(p,e,u,m,g,w){const r=t("ArticleCover"),n=t("ArticleTableScroll");return s(),i("div",null,[a(r,{image:"/assets/current-context-20260916/failed-check-memory.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"The check failed. Why did the AI remember the answer?",summary:"A failed run can still leave an unchecked answer in the next conversation. A controlled experiment separates the error shown now from the history replayed later.",version:"2026-09-16",languageHref:"/zh/engineering/2026-09-16-failed-check-memory",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="the-check-failed-why-did-the-ai-remember-the-answer" tabindex="-1">The check failed. Why did the AI remember the answer? <a class="header-anchor" href="#the-check-failed-why-did-the-ai-remember-the-answer" aria-label="Permalink to &quot;The check failed. Why did the AI remember the answer?&quot;">​</a></h1><p>Imagine using an AI assistant: it produces an answer, but the program meant to check that answer fails.</p><p>On your next question, you might expect the unchecked answer to stay out of the conversation. <strong>In our controlled comparison, the old logic raised an error and saved the answer anyway. The next model call received it.</strong></p><p>The error ended the current attempt without keeping that answer out of the next one.</p><h2 id="what-does-remember-mean-here" tabindex="-1">What does “remember” mean here? <a class="header-anchor" href="#what-does-remember-mean-here" aria-label="Permalink to &quot;What does “remember” mean here?&quot;">​</a></h2><p>It means something specific: the application saves conversation history and sends some of it back to the model with the next question. We did not test model training or a chat product&#39;s long-term memory feature.</p><p>Once an unchecked answer enters that history, a later model call can receive it as context. An unconfirmed statement might then become a premise for another answer. That possible consequence motivated us; what our experiment directly established was whether the earlier answer was sent again.</p><p>The source was <a href="https://github.com/openai/openai-agents-js/pull/1938" target="_blank" rel="noreferrer">OpenAI Agents JS #1938</a>, submitted by jbeckwith-oai. This library connects models, tools, and conversations. Developers can arrange checks on an answer: a check may pass, reject the answer, or fail before reaching a verdict.</p><p>The old implementation already handled “the check says no.” This patch addressed “the check could not finish.” For our research on assistants that keep working across turns, the important question was whether that interruption could leave something behind.</p><h2 id="break-the-checker-then-ask-another-question" tabindex="-1">Break the checker, then ask another question <a class="header-anchor" href="#break-the-checker-then-ask-another-question" aria-label="Permalink to &quot;Break the checker, then ask another question&quot;">​</a></h2><p>Our test model always returned the same distinctive marker text. We made the checks pass, reject, throw an error, or combine one passing check with another that threw. Then we ran another turn and inspected the history actually sent to its model.</p><p>A script supplied the model&#39;s answers; real library code ran the conversation and handled storage. We used four execution/storage combinations and compared the old decision with the fixed one:</p><table tabindex="0"><thead><tr><th>Check outcome</th><th>Old logic: answer replayed</th><th>Fixed logic: answer replayed</th></tr></thead><tbody><tr><td>All pass</td><td>4/4</td><td>4/4</td></tr><tr><td>Explicit rejection</td><td>0/4</td><td>0/4</td></tr><tr><td>Check throws</td><td><strong>4/4</strong></td><td><strong>0/4</strong></td></tr><tr><td>One passes, another throws</td><td><strong>4/4</strong></td><td><strong>0/4</strong></td></tr></tbody></table><p>Four means two ways of returning an answer—streaming or all at once—crossed with two session-storage implementations. These are constructed cases, not production incident rates. Both versions together produced 32 observations.</p><p>The last two rows show the change: <strong>an answer without completed validation was replayed under the old decision and withheld under the fix.</strong> Passing answers still remained, as did previously accepted history and the current user question.</p><p><img src="'+h+'" alt="Checks and conversation memory"></p><p><em>Figure 1. Whether an answer reaches the next turn after a check fails. Source: our pinned-source experiments and saved observations; diagram by the authors. Counts describe constructed cases.</em></p><h2 id="an-unfinished-check-has-not-proved-the-answer-wrong" tabindex="-1">An unfinished check has not proved the answer wrong <a class="header-anchor" href="#an-unfinished-check-has-not-proved-the-answer-wrong" aria-label="Permalink to &quot;An unfinished check has not proved the answer wrong&quot;">​</a></h2><p>A check can fail because its service is unavailable. That does not establish that the answer itself is bad. Equally, one passing check cannot supply the conclusion of another check that failed.</p><p>The fixed behavior preserves that distinction. It does not declare the answer disproved, and it does not automatically admit the answer as context for later work.</p><p>This suggests a practical design choice. An application can retain what the model produced to help diagnose a failed attempt, while keeping that record out of the next model call. <strong>Retaining an attempt and admitting it into subsequent context need separate rules.</strong></p><p>Even completed checks establish acceptance only under their configured requirements. They do not guarantee real-world truth.</p><h2 id="when-checking-recovers-which-answer-should-it-check" tabindex="-1">When checking recovers, which answer should it check? <a class="header-anchor" href="#when-checking-recovers-which-answer-should-it-check" aria-label="Permalink to &quot;When checking recovers, which answer should it check?&quot;">​</a></h2><p>Suppose the service recovers after the answer has been regenerated or the user has changed the question. Which piece of content does a late “pass” actually approve?</p><p>Neither this patch nor our experiment implements deferred verification. The comparison nevertheless leads to a concrete design question: a future retry would need to associate answer content, conversation turn, and checking rules, so that an old verdict cannot be attached to a new answer.</p><p>Developers can start with a small experiment: make the checker throw, run another turn, and inspect what the model receives. Users can provide useful leads too: does an answer marked as failed later reappear as an already-established fact? Saving the surrounding conversation and error message gives an investigator more to work with than “the AI remembered incorrectly.”</p><details><summary>For technical readers: versions, full method, and reproduction</summary><p>The PR by jbeckwith-oai merged on 2026-09-15 UTC. Candidate: <code>457dfff8ce30d19ccbd4a3796ec482356dc19dfa</code>. The control replaces only <code>runner/guardrails.ts</code> with its exact predecessor from <code>8ac97dfedd0395beeb38edb0a17b83a9b89c3354</code>. This was the PR&#39;s only changed production module; other candidate code stayed constant.</p><p>The probe uses public <code>run</code>, ScriptedModel, MemorySession, and an append-only session. It observes both stored items and subsequent model input in streaming and non-streaming modes: four check outcomes × two run modes × two session types × two versions = 32 observations. The mixed-check case establishes a failing batch, not a controlled order of check completion.</p><p>We separately ran the corresponding upstream test file: 71 tests passed, including additional tool-output behavior. That count is not added to the custom observations as a reliability score. No live model service or external database was used, and correctness for every custom store is not established.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-16-current-context" target="_blank" rel="noreferrer">Pinned source, saved observations, and runnable probes</a>. This does not establish a corresponding CodeFlowMu defect.</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',28))])}const k=o(d,[["render",l]]);export{f as __pageData,k as default};
